package com.auca.teacher;
import com.auca.abstracts.AcademicMember; import com.auca.department.Department; import com.auca.exceptions.ValidationException; import java.time.LocalDate; import java.math.BigDecimal;
public class Teacher extends AcademicMember {
 private String employeeNumber,specialization,officeNumber,employmentType; private LocalDate hireDate; private BigDecimal salary;
 public Teacher(String personId,String firstName,String lastName,String email,String phoneNumber,LocalDate dob,String memberNumber,Department department,LocalDate joinDate,String academicStatus,String institutionalEmail,String advisorName,String employeeNumber,String specialization,LocalDate hireDate,BigDecimal salary,String officeNumber,String employmentType){super(personId,firstName,lastName,email,phoneNumber,dob,memberNumber,department,joinDate,academicStatus,institutionalEmail,advisorName);this.employeeNumber=employeeNumber;this.specialization=specialization;this.hireDate=hireDate;this.salary=salary;this.officeNumber=officeNumber;this.employmentType=employmentType;}
 public String getRoleDescription(){return "Teacher";} public String getAcademicCategory(){return "Academic staff";}
 public void validate() throws ValidationException {super.validate();if(employeeNumber==null||employeeNumber.isBlank()||specialization==null||specialization.isBlank()||hireDate==null||salary==null||salary.compareTo(BigDecimal.ZERO)<=0||officeNumber==null||officeNumber.isBlank()||employmentType==null||employmentType.isBlank())throw new ValidationException("Invalid teacher details; salary must be positive.");}
 public String getEmployeeNumber(){return employeeNumber;} public void setEmployeeNumber(String v){employeeNumber=v;} public String getSpecialization(){return specialization;} public void setSpecialization(String v){specialization=v;} public LocalDate getHireDate(){return hireDate;} public void setHireDate(LocalDate v){hireDate=v;} public BigDecimal getSalary(){return salary;} public void setSalary(BigDecimal v){salary=v;} public String getOfficeNumber(){return officeNumber;} public void setOfficeNumber(String v){officeNumber=v;} public String getEmploymentType(){return employmentType;} public void setEmploymentType(String v){employmentType=v;}
 public String getId(){return employeeNumber;} public String getDisplayName(){return getFirstName()+" "+getLastName()+" ("+employeeNumber+")";} public String toString(){return "TEACHER\n"+super.toString()+", Employee No: "+employeeNumber+", Specialization: "+specialization+", Hire date: "+hireDate+", Salary: "+salary+", Office: "+officeNumber+", Employment: "+employmentType;}
}
